import{_ as i,a0 as o,w as r,s as d,ao as p,I as t,x as a,a1 as e,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"通過“猜數字”遊戲學習 Tcl | LCTT x X-CMD","titleTemplate":false,"description":"通過“猜數字”遊戲學習 Tcl | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通過“猜數字”遊戲學習 Tcl | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通過“猜數字”遊戲學習 Tcl | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20230209.3 ⭐️⭐️ Learn Tcl by writing a simple game","title":"通過“猜數字”遊戲學習 Tcl","tag":"202302","desc":""},"relativePath":"202302/20230209.3 ⭐️⭐️ Learn Tcl by writing a simple game.md","filePath":"[post].md"}'),c={name:"202302/20230209.3 ⭐️⭐️ Learn Tcl by writing a simple game.md"};function g(u,s,h,b,k,m){const n=o("Link");return r(),d("div",null,[s[24]||(s[24]=p(`<h1 id="通過-猜數字-遊戲學習-tcl" tabindex="-1">通過“猜數字”遊戲學習 Tcl <a class="header-anchor" href="#通過-猜數字-遊戲學習-tcl" aria-label="Permalink to “通過“猜數字”遊戲學習 Tcl”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202302/23/140000ilg3oa8khgrhr1r3.jpg" alt=""></p><blockquote><p>探索 Tcl 的基本語言結構，包括用户輸入、輸出、變量、條件評估、循環和簡單函數。</p></blockquote><p>我的 Tcl 之旅始於最近需要將一個困難的基於 Java 的命令列配置工具自動化。我使用 Ansible 做了一些自動化編程，偶爾也會使用 <code>expect</code> 模組。坦率地説，我發現這個模組的作用有限，原因包括：難以對相同的提示進行排序，難以捕捉到額外步驟的值，控制邏輯的靈活性有限，等等。有時你可以用 <code>shell</code> 模組來代替。但有時你會遇到那種特立獨行、過於複雜的命令列程序，似乎無法實現自動化。</p><p>就我而言，我正在自動安裝我公司的一個程序。最後的配置步驟只能通過命令列來完成，通過幾個不規範的、重複的提示和需要捕捉的數據輸出。好在傳統的 Expect 是唯一的答案。要使用 Expect 的基本功能，並不需要對 Tcl 有很深的瞭解，但你瞭解的越多，你就能從它那裏得到更多的力量。這是後續文章的話題。現在，我探討一下 Tcl 的基本語言結構，包括用户輸入、輸出、變量、條件判斷、循環和簡單函數。</p><h3 id="安裝-tcl" tabindex="-1">安裝 Tcl <a class="header-anchor" href="#安裝-tcl" aria-label="Permalink to “安裝 Tcl”">​</a></h3><p>在 Linux 系統上，我使用這個：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install tcl</span></span>
<span class="line"><span># which tclsh</span></span>
<span class="line"><span>/bin/tclsh</span></span></code></pre></div>`,8)),t("p",null,[s[1]||(s[1]=a("在 macOS 上，你可以使用 ",-1)),e(n,{href:"https://opensource.com/article/20/6/homebrew-mac"},{default:l(()=>[...s[0]||(s[0]=[a("Homebrew",-1)])]),_:1}),s[2]||(s[2]=a(" 來安裝最新的 Tcl：",-1))]),s[25]||(s[25]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ brew install tcl-tk</span></span>
<span class="line"><span>$ which tclsh</span></span>
<span class="line"><span>/usr/local/bin/tclsh</span></span></code></pre></div><h3 id="在-tcl-中猜數字" tabindex="-1">在 Tcl 中猜數字 <a class="header-anchor" href="#在-tcl-中猜數字" aria-label="Permalink to “在 Tcl 中猜數字”">​</a></h3><p>從創建基本的可執行腳本 <code>numgame.tcl</code> 開始：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch numgame.tcl</span></span>
<span class="line"><span>$ chmod 755 numgame.tcl</span></span></code></pre></div><p>接着在你的文件中開始編碼，標題是通常的 #!：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/tclsh</span></span></code></pre></div><p>這裏有一些關於 Tcl 的簡單介紹，以便與本文一起追蹤。</p><p>第一點是，Tcl 處理的都是字符串。變量通常被當作字符串處理，但可以自動切換類型和內部表示（這一點你通常無法看到）。函數可以把它們的字符串參數解釋為數字（<code>expr</code>），並且只通過值傳遞。字符串通常使用雙引號或大括號來劃分。雙引號允許變量擴展和轉義序列，而大括號則完全沒有擴展。</p><p>第二點是 Tcl 語句可以用分號隔開，但通常不這樣。語句行可以用反斜槓字符來分割，然而，典型的做法是將多行語句放在大括號內，以避免需要這樣做。大括號只是更簡單，下面的代碼格式也反映了這一點。大括號允許對字符串進行延遲求值。在 Tcl 進行變量替換之前，值被傳遞給函數。</p><p>最後，Tcl 使用方括號進行命令替換。方括號之間的任何東西都會被送到 Tcl 解釋器的一個新的遞歸調用中進行求值。這對於在表達式中間調用函數或為函數生成參數是很方便的。</p><h3 id="過程" tabindex="-1">過程 <a class="header-anchor" href="#過程" aria-label="Permalink to “過程”">​</a></h3><p>雖然在這個遊戲中沒有必要，但我先舉一個在 Tcl 中定義函數的例子，你可以在以後使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>proc used_time {start} {</span></span>
<span class="line"><span>	return [expr [clock seconds] - $start]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>使用 <code>proc</code> 將其設定為一個函數（或過程）定義。接下來是函數的名稱。然後是一個包含參數的列表；在本例中是一個參數 <code>{start}</code> ，然後是函數主體。注意，主體的大括號在這一行開始，它不能在下面一行。該函數返回一個值。返回值是一個複合求值（方括號），它從讀取系統時鐘 <code>[clock seconds]</code> 開始，並進行數學運算以減去 <code>$start</code> 參數。</p><h3 id="設置、邏輯和完成" tabindex="-1">設置、邏輯和完成 <a class="header-anchor" href="#設置、邏輯和完成" aria-label="Permalink to “設置、邏輯和完成”">​</a></h3><p>你可以在這個遊戲的其餘部分增加更多的細節，進行一些初始設置，對玩家的猜測進行迭代，然後在完成後打印結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>set num [expr round(rand()*100)]</span></span>
<span class="line"><span>set starttime [clock seconds]</span></span>
<span class="line"><span>set guess -1</span></span>
<span class="line"><span>set count 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>puts &quot;Guess a number between 1 and 100&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>while { $guess != $num } {</span></span>
<span class="line"><span>	incr count</span></span>
<span class="line"><span>	puts -nonewline &quot;==&gt; &quot;</span></span>
<span class="line"><span>	flush stdout</span></span>
<span class="line"><span>	gets stdin guess</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	if { $guess &lt; $num } {</span></span>
<span class="line"><span>		puts &quot;Too small, try again&quot;</span></span>
<span class="line"><span>	} elseif { $guess &gt; $num } {</span></span>
<span class="line"><span>		puts &quot;Too large, try again&quot;</span></span>
<span class="line"><span>	} else {</span></span>
<span class="line"><span>		puts &quot;That&#39;s right!&quot;</span></span>
<span class="line"><span>	}</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>set used [used_time $starttime]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>puts &quot;You guessed value $num after $count tries and $used elapsed seconds&quot;</span></span></code></pre></div><p>前面的 <code>set</code> 語句建立變量。前兩個求值表達式用於識別 1 到 100 之間的隨機數，下一個保存系統時鐘啓動時間。</p><p><code>puts</code> 和 <code>gets</code> 命令用於來自玩家的輸出和輸入。我使用的 <code>puts</code> 暗示輸出是標準輸出。<code>gets</code> 需要定義輸入通道，所以這段代碼指定 <code>stdin</code> 作為用户的終端輸入源。</p><p>當 <code>puts</code> 省略行末終止符時，需要 <code>flush stdout</code> 命令，因為 Tcl 緩衝了輸出，在需要下一個 I/O 之前可能不會被顯示。</p><p>從這裏開始，<code>while</code> 語句説明了循環控制結構和條件邏輯，需要給玩家反饋並最終結束循環。</p><p>最後的 <code>set</code> 命令調用我們的函數來計算遊戲的耗時秒數，接着是收集到的統計數字來結束遊戲。</p><h3 id="玩吧" tabindex="-1">玩吧! <a class="header-anchor" href="#玩吧" aria-label="Permalink to “玩吧!”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./numgame.tcl</span></span>
<span class="line"><span>Guess a number between 1 and 100</span></span>
<span class="line"><span>==&gt; 100</span></span>
<span class="line"><span>Too large, try again</span></span>
<span class="line"><span>==&gt; 50</span></span>
<span class="line"><span>Too large, try again</span></span>
<span class="line"><span>==&gt; 25</span></span>
<span class="line"><span>Too large, try again</span></span>
<span class="line"><span>==&gt; 12</span></span>
<span class="line"><span>Too large, try again</span></span>
<span class="line"><span>==&gt; 6</span></span>
<span class="line"><span>Too large, try again</span></span>
<span class="line"><span>==&gt; 3</span></span>
<span class="line"><span>That&#39;s right!</span></span>
<span class="line"><span>You guessed value 3 after 6 tries and 20 elapsed seconds</span></span></code></pre></div><h3 id="繼續學習" tabindex="-1">繼續學習 <a class="header-anchor" href="#繼續學習" aria-label="Permalink to “繼續學習”">​</a></h3>`,25)),t("p",null,[s[4]||(s[4]=a("當我開始這個練習時，我懷疑回到 90 年代末的流行語言對我有多大的幫助。一路走來，我發現 Tcl 有幾處讓我非常喜歡的地方，我最喜歡的是方括號內的命令求值。與其他許多過度使用複雜閉包結構的語言相比，它似乎更容易閲讀和使用。我以為它是一種 ",-1)),e(n,{href:"https://opensource.com/article/19/6/favorite-dead-language"},{default:l(()=>[...s[3]||(s[3]=[a("已消亡的語言",-1)])]),_:1}),s[5]||(s[5]=a("，但實際上它仍在蓬勃發展，並在多個平台上得到支持。我學到了一些新的技能，並對這種古老的語言有了新的認識。",-1))]),t("p",null,[s[7]||(s[7]=a("在 ",-1)),e(n,{href:"https://www.tcl-lang.org"},{default:l(()=>[...s[6]||(s[6]=[a("https://www.tcl-lang.org",-1)])]),_:1}),s[8]||(s[8]=a(" 上查看官方網站。你可以找到最新的源代碼、二進制發行版、論壇、文檔，以及仍在進行的會議信息的參考。",-1))]),s[26]||(s[26]=t("hr",null,null,-1)),t("p",null,[s[10]||(s[10]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/23/2/learn-tcl-writing-simple-game"},{default:l(()=>[...s[9]||(s[9]=[a("https://opensource.com/article/23/2/learn-tcl-writing-simple-game",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/jamesf"},{default:l(()=>[...s[11]||(s[11]=[a("James Farrell",-1)])]),_:1}),s[16]||(s[16]=a(" 選題：",-1)),e(n,{href:"https://github.com/lkxed/"},{default:l(()=>[...s[12]||(s[12]=[a("lkxed",-1)])]),_:1}),s[17]||(s[17]=a(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:l(()=>[...s[13]||(s[13]=[a("geekpi",-1)])]),_:1}),s[18]||(s[18]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:l(()=>[...s[14]||(s[14]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[21]||(s[21]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[19]||(s[19]=[a("LCTT",-1)])]),_:1}),s[22]||(s[22]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:l(()=>[...s[20]||(s[20]=[a("Linux中國",-1)])]),_:1}),s[23]||(s[23]=a(" 榮譽推出",-1))])])}const y=i(c,[["render",g]]);export{x as __pageData,y as default};
